with lines as (select id, currency, element from price_tiers lateral view outer explode(tier_prices) x as element) select *, rank() over (order by element desc) as element_rank, dense_rank() over (partition by currency order by element desc nulls first) as element_dense_rank, min(element) over (partition by currency) as currency_min_element, count(element) over (partition by currency) as currency_count_element, avg(element) over (partition by currency) as currency_avg_element from lines;
